head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS20900.xml';
scwin.vBndClssCd, scwin.vBndTpNm;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();
scwin.processGp;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //등록 1, 삭제 5

/********************************************** 
 * 함수명  	 : fn_SearchBnd
 * 설명       : 채권분류 리스트를 조회 한다.
 ***********************************************/
scwin.fn_SearchBnd = function() {
    var dsNm = 'BNS_BND_CLSS';
    var qryId = 'lds.stf.bnslistbzappl.select.selectBndClss';
    var param = '&{P}V_BND_CLSS_CD=' + $c.stf.getObjectValue(txb_BndTpNm);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_BndList);
};


/********************************************** 
 * 함수명  	 : fn_SearchIsur
 * 설명       : 발행기관 리스트를 조회 한다.
 ***********************************************/
scwin.fn_SearchIsur = function() {
    var dsNm = 'BNS_ISUR_INFO';
    var qryId = 'lds.stf.bnslistbzappl.select.selectBndIsur';
    var param = '&{P}V_BND_CLSS_CD=' + scwin.vBndClssCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsurList, dsNm, qryId, param);
    $c.bns.ShowWinArrPnlRight(pnl_info, grd_IsurList);
};


/********************************************** 
 * 함수명   : fn_ShowBndClss
 * 설명       : 채권분류 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowBndClss = function(txb_Dtl) {
    scwin.fn_GetPar = fn_GetParBndClssCd;
    scwin.fn_SetPar = fn_SetParBndClssCd;
    $c.bns.fn_PopBndClssCdSearch(txb_Dtl);
};

/********************************************** 
 * 함수명   : fn_GetParBndClssCd
 * 설명       : 채권분류 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParBndClssCd = function(arrPar) {
    scwin.arrPar[0] = {
        BND_CLSS_CD: $c.stf.getObjectValue(txb_BndClssCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParBndClssCd
 * 설명       : 채권분류 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParBndClssCd = function(arrPar) {
    $c.stf.setObjectValue(txb_BndClssCd, scwin.arrPar[0].BND_CLSS_CD);
    $c.stf.setObjectValue(txb_BndTpNm_in, scwin.arrPar[0].BND_TP_NM);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(txb_Dtl) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(txb_Dtl);
};

/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurCd, scwin.arrPar[0].ISUR_CD);
    $c.stf.setObjectValue(txb_IsurNm, scwin.arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_ClearTextField
 * 설명       : 텍스트 필드를 초기화 한다.
 ***********************************************/
scwin.fn_ClearTextField = function() {
    $c.stf.setObjectValue(txb_BndClssCd, '');
    $c.stf.setObjectValue(txb_BndTpNm_in, '');
    $c.stf.setObjectValue(txb_IsurCd, '');
    $c.stf.setObjectValue(txb_IsurNm, '');
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(txb_BndClssCd) == '' || $c.stf.getObjectValue(txb_BndTpNm_in) == '') {
        $c.win.alert("[채권분류코드]를 선택해 주십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_IsurCd) == '' || $c.stf.getObjectValue(txb_IsurNm) == '') {
        $c.win.alert("[발행기관코드]를 선택해 주십시오.");
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_DuplCheck
 * 설명      : 중복 등록 체크
 ***********************************************/
scwin.fn_DuplCheck = function(GUBUN) {
    var dsNm = 'BNS_ISUR_BND_CLSS';
    var qryId = 'lds.stf.bnslistbzappl.select.selectCheckDupl';
    var param = '&{P}V_BND_CLSS_CD=' + $c.stf.getObjectValue(txb_BndClssCd);
    param += '&{P}V_ISUR_CD=' + $c.stf.getObjectValue(txb_IsurCd);
    param += '&{P}V_GUBUN=' + GUBUN;
    dts_CheckDupl.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckDupl, dsNm, qryId, param);
    return dts_CheckDupl.getTotalRow();
};


/********************************************** 
 * 함수명		: fn_SetDataSet
 * 설명			: 텍스트 필드를 데이터셋에 설정
 ***********************************************/
scwin.fn_SetDataSet = function() {
    dts_SaveItem.insertRow();
    dts_SaveItem.setCellData(1, "BND_CLSS_CD", $c.stf.getObjectValue(txb_BndClssCd));
    dts_SaveItem.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_IsurCd));
};


/********************************************** 
 * 함수명		: fn_Insert
 * 설명			: 발행기관 채권분류 등록
 ***********************************************/
scwin.fn_Insert = function() {
    if (scwin.fn_InputCheck() == false) return;
    if (scwin.fn_DuplCheck('ISUR_DUPL') != 0) {
        var vAnswer = confirm('기등록된 발행기관입니다. 그래도 처리하시겠습니까?');
        if (!vAnswer) return;
    }
    if (scwin.fn_DuplCheck('REG_DUPL') != 0) {
        $c.win.alert("등록된 코드가 있습니다.");
        return;
    }
    var vAnswer = confirm('발행기관 채권분류 등록하시겠습니까?');
    if (vAnswer == true) {
        var url = "/bns/ListBzAppl.do?method=createIsurBndClss";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        scwin.fn_SetDataSet();
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_SaveItem)";
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명		: fn_Delete
 * 설명			: 발행기관 채권분류 삭제
 ***********************************************/
scwin.fn_Delete = function() {
    if (fn_InputCheck == false) return;
    var vAnswer = confirm('발행기관 채권분류 삭제하시겠습니까?');
    if (vAnswer == true) {
        var url = "/bns/ListBzAppl.do?method=deleteIsurBndClss";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        scwin.fn_SetDataSet();

        /**
         * 	- 변경된 데이터가 없더라도 데이터셋 전송하여 접수 진행
         */
        dts_SaveItem.UseChangeInfo = "False";
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_SaveItem)";
        trs_Save.Post();
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_IsurSearch);
    $c.bns.BnsPanelToGroupBox(pnl_info);
    scwin.fn_ClearTextField();

    //가우스헤더 셋팅(입력항목)
    dts_SaveItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_ISUR_BND_CLSS";
    dts_SaveItem.Reset();

    //조회
    scwin.fn_SearchBnd();
};
scwin.txb_BndTpNm_onkeypress = function() {
    if (event.keyCode == 13) scwin.fn_SearchBnd();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_SearchBnd();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_BndList);
    dts_List.setRowPosition(0, 0);
};
scwin.grd_BndList_OnClick = function(row) {
    scwin.fn_ClearTextField();
    scwin.vBndClssCd = dts_List.getCellData(row, "BND_CLSS_CD");
    scwin.vBndTpNm = dts_List.getCellData(row, "BND_TP_NM");
    $c.stf.setObjectValue(txb_BndClssCd, scwin.vBndClssCd);
    $c.stf.setObjectValue(txb_BndTpNm_in, scwin.vBndTpNm);
    if (dts_List.getTotalRow() != 0) scwin.fn_SearchIsur();
};
scwin.dts_IsurList_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_IsurList_OnLoadCompleted = function(rowcount) {
    $c.bns.CloseWinArrPnlRight(rowcount, pnl_info, grd_IsurList);
    dts_IsurList.setRowPosition(0, 0);
};
scwin.grd_IsurList_OnClick = function(row) {
    if (dts_IsurList.getTotalRow() != 0) {
        $c.stf.setObjectValue(txb_IsurCd, dts_IsurList.getCellData(row, "ISUR_CD"));
        $c.stf.setObjectValue(txb_IsurNm, dts_IsurList.getCellData(row, "ISUR_NM"));
    }
};
scwin.img_com_srch_onclick = function() {
    scwin.fn_ShowIsur(txb_IsurNm);
};
scwin.img_BndClssTp_onclick = function() {
    scwin.fn_ShowBndClss(lbl_Dtl);
};
scwin.btn_Save_onclick = function() {
    scwin.processGp = '1';
    scwin.fn_Insert();
};
scwin.btn_Del_onclick = function() {
    scwin.processGp = '5';
    scwin.fn_Delete();
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    }
    if (scwin.processGp == '5') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    }
    $c.stf.setObjectValue(txb_IsurCd, "");
    $c.stf.setObjectValue(txb_IsurNm, "");
    dts_IsurList.Reset();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    }
    if (scwin.processGp == '5') {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    }
};
